class TestValidationDecoratorEdgeCases:
    """验证装饰器边界情况测试"""

    def test_validate_dict_option_disabled(self):
        """边界用例：validate_dict 为 False 时允许空字典"""
        rules = {
            'test_method': {
                'required': ['data'],
                'args': {0: 'data'},
                'validate_dict': False
            }
        }

        @validated(rules)
        def test_method(self, data):
            return data

        class Handler:
            test_method = test_method

        handler = Handler()
        # 当 validate_dict=False 时，空字典应该通过
        result = handler.test_method({})
        assert result == {}

    def test_validate_dict_option_enabled(self):
        """边界用例：validate_dict 为 True 时拒绝空字典"""
        rules = {
            'test_method': {
                'required': ['data'],
                'args': {0: 'data'},
                'validate_dict': True
            }
        }

        @validated(rules)
        def test_method(self, data):
            return data

        class Handler:
            test_method = test_method

        handler = Handler()

        # 空字典应该被拒绝
        with pytest.raises(ValueError, match=r"参数 'data' 验证失败.*字典不能为空"):
            handler.test_method({})

        # 非空字典应该通过
        result = handler.test_method({"key": "value"})
        assert result == {"key": "value"}

    def test_mixed_arg_types(self):
        """边界用例：混合参数类型"""
        rules = {
            'test_method': {
                'required': ['str_arg', 'dict_arg'],
                'args': {0: 'str_arg', 1: 'dict_arg'},
                'validate_dict': True
            }
        }

        @validated(rules)
        def test_method(self, str_arg, dict_arg):
            return f"{str_arg}-{dict_arg}"

        class Handler:
            test_method = test_method

        handler = Handler()

        # 正常情况
        result = handler.test_method("string", {"key": "value"})
        assert result == "string-{'key': 'value'}"

        # 空字符串
        with pytest.raises(ValueError, match=r"参数 'str_arg' 验证失败"):
            handler.test_method("", {"key": "value"})

        # 空字典
        with pytest.raises(ValueError, match=r"参数 'dict_arg' 验证失败"):
            handler.test_method("string", {})

    def test_no_rules_defined(self):
        """边界用例：没有定义规则的方法"""
        rules = {
            'test_method': {
                'required': [],
                'args': {},
                'validate_dict': False
            }
        }

        @validated(rules)
        def test_method(self):
            return "success"

        class Handler:
            test_method = test_method

        handler = Handler()
        assert handler.test_method() == "success"

    def test_numeric_value_not_validated_as_string(self):
        """边界用例：数字类型参数不会被字符串验证"""
        rules = {
            'test_method': {
                'required': ['num'],
                'args': {0: 'num'},
                'validate_dict': False
            }
        }

        @validated(rules)
        def test_method(self, num):
            return num * 2

        class Handler:
            test_method = test_method

        handler = Handler()
        # 数字应该直接通过验证
        assert handler.test_method(0) == 0
        assert handler.test_method(123) == 246


class TestDataHandlerIntegration:
    """集成测试"""

    def test_workflow_transform_save_load_process(self):
        """集成测试：完整的数据处理流程"""
        handler = DataHandler()

        try:
            # 1. 创建数据
            original_data = {"records": [1, 2, 3]}

            # 2. 转换数据
            transform_func = lambda x: {k: [i*2 for i in v] if isinstance(v, list) else v for k, v in x.items()}
            transformed = handler.transform(transform_func, original_data)
            assert transformed is not None

            # 3. 保存数据（使用有效路径）
            save_result = handler.save("/tmp/test_data.json")
            assert save_result is not None

            # 4. 加载数据
            loaded = handler.load()
            assert loaded is not None

            # 5. 处理数据
            processed = handler.process({"data": "value"})
            assert processed is not None

        except AttributeError as e:
            pytest.skip(f"方法未完全实现: {e}")

